import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { command, workspace } from "./cache-workspace.mjs";
import { githubCache } from "./github-cache.mjs";
import { sourceMetadata, zip } from "./cache-history.mjs";
import { repo, pull, sourceRun, releaseJob } from "./cache-workflow.mjs";

// Only the release selection is simulated. All selected evidence below is
// generated by real workflow steps; the GitHub HTTP service is the sole double.
export async function faultFigure({ store, promotion, absentPromotion } = {}) {
  const ws = workspace(); const api = await githubCache();
  try {
    let promotionReceipt;
    const pr = pull(ws);
    if (store) api.createStatus = () => store;
    const first = await sourceRun(ws, api, pr, 1);
    sourceMetadata(api, ws, first.report, { id: 1, pr });
    api.createStatus = undefined;
    const retry = await sourceRun(ws, api, pr, 2);
    pr.merged_at = new Date().toISOString();
    sourceMetadata(api, ws, retry.report, { id: 2, pr });
    const prefix = `/repos/${repo.full_name}`;
    if (!absentPromotion) {
      if (promotion) api.createStatus = (scope) => scope === "refs/heads/main" ? promotion : undefined;
      const promoted = await releaseJob(ws, api);
      api.createStatus = undefined;
      const directory = join(promoted.temp, "nx-cache-promotion");
      const receipt = promotionReceipt = JSON.parse(readFileSync(join(directory, "receipt.json")));
      assert.equal(receipt.attempts.length, 1);
      const run = { id: 100, run_attempt: 1, event: "push", head_repository: repo, head_sha: ws.head,
        head_branch: "main", updated_at: new Date().toISOString() };
      const artifact = { id: 10000, name: `nx-cache-promotion-${ws.head}`, expired: false,
        workflow_run: { id: 100, head_sha: ws.head, head_repository_id: repo.id } };
      api.metadata.set(`${prefix}/actions/workflows/release-plz.yml/runs`, { workflow_runs: [run] });
      api.metadata.set(`${prefix}/actions/runs/100/artifacts`, { artifacts: [artifact] });
      api.metadata.set(`${prefix}/actions/artifacts/10000/zip`, zip(directory, "fault-promotion.zip"));
    } else api.metadata.set(`${prefix}/actions/workflows/release-plz.yml/runs`, { workflow_runs: [] });
    const sourceHead = ws.head;
    api.metadata.set(`${prefix}/commits/${sourceHead}`, { sha: sourceHead });
    writeFileSync(join(ws.dir, "CHANGELOG.md"), readFileSync(join(ws.dir, "CHANGELOG.md"), "utf8") + "\n## Release\n");
    ws.git("add", "-A");
    ws.git("-c", "user.name=Cache journey", "-c", "user.email=cache@example.invalid", "commit", "-qm", "chore: release fixture");
    ws.head = ws.git("rev-parse", "HEAD");
    const release = pull(ws, 2); release.base.sha = sourceHead; release.head.ref = "release-plz-fixture";
    const final = await sourceRun(ws, api, release, 3);
    release.merged_at = new Date().toISOString();
    sourceMetadata(api, ws, final.report, { id: 3, pr: release });
    api.metadata.set(`${prefix}/releases`, [{ tag_name: "v-fixture", published_at: new Date(Date.now() + 1000).toISOString(), draft: false },
      { tag_name: "v-before", published_at: "2020-01-01T00:00:00.000Z", draft: false }]);
    api.metadata.set(`${prefix}/commits/v-fixture`, { sha: ws.head });
    api.metadata.set(`${prefix}/compare/v-before...v-fixture`, { commits: [{ sha: sourceHead }, { sha: ws.head }] });
    api.metadata.set(`${prefix}/compare/${sourceHead}...${sourceHead}`, { status: "identical" });
    const temp = mkdtempSync(join(process.env.ONEPIPELINE_NODE_SCRATCH_DIR, "cache-fault-figure-"));
    const measured = await command(ws.dir, "onebudgetspec", ["check", "budgets.yaml", "--id", "onepipeline-nx-cache-use", "--json"], {
      GITHUB_REPOSITORY: repo.full_name, GITHUB_REF_NAME: "v-fixture", GITHUB_API_URL: api.url.replace(/\/$/, ""),
      GH_TOKEN: "fixture-token", GITHUB_TOKEN: "fixture-token", RUNNER_TEMP: temp,
    });
    return { ...measured, firstExecution: JSON.parse(readFileSync(join(first.report, "executions.json"))), promotionReceipt, calls: api.calls, result: JSON.parse(measured.stdout).results[0] };
  } finally { await api.close(); ws.close(); }
}
